#include "network_structures.h"
#include <stdio.h>
#include <time.h>
enum{ROUTES=20000,LOOKUPS=200000,FLOWS=100000};static double e(struct timespec a,struct timespec b){return(double)(b.tv_sec-a.tv_sec)+(double)(b.tv_nsec-a.tv_nsec)/1e9;}static FlowKey key(int i){FlowKey k={(uint32_t)i,(uint32_t)(i*17),(uint16_t)(1000+i%50000),(uint16_t)(80+i%1000),(uint8_t)(i&1?6:17)};return k;}
int main(void){RouteTrie*t=rt_create();FlowTable*f=flow_create(1024);if(!t||!f)return 1;for(int i=0;i<ROUTES;++i)if(!rt_add(t,(uint32_t)i<<12,20,(uint32_t)i))return 2;struct timespec a,b,c;timespec_get(&a,TIME_UTC);uint64_t sum=0;for(int i=0;i<LOOKUPS;++i){uint32_t hop=0;uint8_t len=0;bool found=false;if(!rt_lookup(t,((uint32_t)(i%ROUTES)<<12)|7,&hop,&len,&found)||!found)return 3;sum+=hop+len;}timespec_get(&b,TIME_UTC);for(int i=0;i<FLOWS;++i){bool ins=false;if(!flow_put(f,key(i),(uint64_t)i,&ins)||!ins)return 4;}for(int i=0;i<FLOWS;++i){uint64_t v=0;bool found=false;if(!flow_get(f,key(i),&v,&found)||!found)return 5;sum+=v;}timespec_get(&c,TIME_UTC);printf("route_lookup_seconds=%.6f flow_insert_lookup_seconds=%.6f checksum=%llu\n",e(a,b),e(b,c),(unsigned long long)sum);flow_free(f);rt_free(t);return 0;}
